<script setup>
import {ref,computed} from 'vue';
import {can,fieldAccess,money,cents,approvalStage,approvalStageLabel,approvalRequirement} from './domain.js';
import {financeStatus,canFinanceAct,invoiceBalance,invoiceStatus,expenseCategories,validDate,financeFields} from './finance.js';
import {poStatus} from './procurement.js';
const props=defineProps(['state','user','tenantId','page','execute','busy','failure']);
const query=ref(''),dialog=ref(''),selected=ref(''),form=ref({}),error=ref(''),formRef=ref(null);
const kind=computed(()=>props.page==='expenses'?'expense':'payment');
const allowed=(a,f=kind.value)=>can(props.state,props.user,props.tenantId,a,f);
const mode=(k,f=kind.value)=>fieldAccess(props.state,props.user,props.tenantId,k,f);
const editable=(f=kind.value)=>financeFields.every(k=>mode(k,f)==='edit');
const records=computed(()=>(kind.value==='expense'?props.state.expenses:props.state.payments).filter(d=>d.tenantId===props.tenantId&&allowed('view')&&JSON.stringify(d).toLowerCase().includes(query.value.toLowerCase())));
const invoices=computed(()=>(props.state.invoices||[]).filter(i=>i.tenantId===props.tenantId&&allowed('view','payment')));
const active=computed(()=>records.value.find(d=>d.id===selected.value));
const inv=id=>invoices.value.find(i=>i.id===id);
const balance=i=>i?i.balance??invoiceBalance(props.state,i):null;
const iStatus=i=>invoiceStatus(props.state,i);
const approved=computed(()=>records.value.filter(d=>financeStatus(props.state,d)==='Approved'));
const approvedTotal=computed(()=>approved.value.reduce((n,d)=>n+(d.amount||0),0));
const pending=computed(()=>records.value.filter(d=>!['Draft','Approved','Rejected'].includes(financeStatus(props.state,d))).length);
const orders=computed(()=>props.state.orders.filter(o=>o.tenantId===props.tenantId&&props.state.vendors.some(v=>v.id===o.vendorId&&!v.deleted&&(!v.onboardingStatus||v.onboardingStatus==='Active'))));
const refs=computed(()=>form.value.referenceType==='work_order'?orders.value:props.state.purchaseOrders.filter(p=>p.tenantId===props.tenantId&&poStatus(props.state,p)==='Approved'));
const extra=computed(()=>props.state.forms.find(f=>f.id===kind.value&&f.version===(form.value.formVersion||Math.max(...props.state.forms.filter(f=>f.id===kind.value).map(f=>f.version))))?.fields||[]);
const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
const required=v=>!!String(v??'').trim()||'Required';
const dateRule=v=>validDate(v)||'Enter a valid date';
const amountRule=v=>{try{return cents(v)>=0||'Use a non-negative value';}catch{return 'Use a number with up to 2 decimals';}};
const showMoney=n=>n==null?'Restricted':money(n);
const date=v=>v?new Date(v+'T00:00:00').toLocaleDateString('en-IN'):'—';
const who=id=>props.state.users.find(u=>u.id===id)?.name||'Project user';
const approveLabel=d=>approvalStageLabel(approvalStage(props.state,props.user,props.tenantId,d,props.state.financeEvents.map(e=>({...e,amendmentId:e.documentId})),d.kind));
function open(type,d){error.value='';dialog.value=type;if(type==='invoice')form.value={orderId:'',description:'',category:'Civil works',invoiceNumber:'',invoiceDate:today(),price:'',remarks:''};else if(type==='invoice-status')form.value={id:d.id,status:iStatus(d)==='Open'?'Closed':'Open',reason:''};else if(kind.value==='expense')form.value=d?{...JSON.parse(JSON.stringify(d)),price:String(d.amount/100)}:{description:'',category:'Consultant charges',payee:'',expenseDate:today(),price:'',referenceType:'',referenceId:'',remarks:'',data:{}};else form.value=d?{...JSON.parse(JSON.stringify(d)),price:String(d.paid/100),tax:String(d.tds/100)}:{invoiceId:'',price:'',tax:'0',paidDate:today(),remarks:'',data:{}};}
async function save(){error.value='';try{if(formRef.value&&!(await formRef.value.validate()).valid)return;let type=dialog.value,d={...form.value};if(type==='invoice')d.amount=cents(d.price);else if(type!== 'invoice-status'){type=kind.value;if(type==='expense')d.amount=cents(d.price);else{d.paid=cents(d.price);d.tds=cents(d.tax);}}const r=await props.execute(type,d,'Record saved');if(r)dialog.value='';}catch(e){error.value=e.message;}}
async function action(d,a){await props.execute('finance-transition',{id:d.id,action:a},'Approval action recorded',false);}
</script>
<template>
<div class="workflow-banner"><v-icon color="primary">{{page==='expenses'?'mdi-receipt-text-outline':'mdi-bank-transfer'}}</v-icon><div><strong>{{page==='expenses'?'Construction expenses with retained approvals':'Vendor payments · net paid + TDS settle the invoice'}}</strong><p>{{page==='expenses'?'Link expenses already covered by an order to avoid adding their cost again.':'Only approved payments reduce balances. This records payments; it does not send funds.'}}</p></div></div>
<div class="stats-grid procurement-stats"><div class="stat-card primary-stat"><div class="stat-label">{{page==='expenses'?'Approved expenses':'Approved settlements'}}</div><strong>{{mode('amount')==='hidden'?'Restricted':money(approvedTotal)}}</strong><span>{{page==='expenses'?'Includes linked expenses; only additional costs increase the project total.':'Settlement = net vendor payout + TDS amount.'}}</span></div><div class="stat-card"><div class="stat-label">Awaiting approval</div><strong>{{pending}}</strong><span>Draft and pending values are excluded.</span></div><div class="stat-card"><div class="stat-label">{{page==='expenses'?'Expense records':'Outstanding invoice balance'}}</div><strong>{{page==='expenses'?records.length:mode('amount')==='hidden'?'Restricted':money(invoices.reduce((n,i)=>n+(balance(i)||0),0))}}</strong><span>{{page==='expenses'?'Consultancy, salaries, materials and site overheads.':'Balance = invoice amount − approved net paid − approved TDS.'}}</span></div></div>
<section v-if="page==='payments'" class="panel mb-6"><div class="panel-top"><div><h2>Vendor invoices</h2><p>Work-order dates and vendor details are filled from the selected project order.</p></div><v-btn v-if="allowed('create')&&editable()" color="primary" prepend-icon="mdi-plus" @click="open('invoice')">Add invoice</v-btn></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>VENDOR / WORK ORDER</th><th>INVOICE / DATE</th><th>DESCRIPTION / CATEGORY</th><th>STATUS</th><th>INVOICE VALUE</th><th>BALANCE</th><th></th></tr></thead><tbody><tr v-for="i in invoices" :key="i.id"><td><strong>{{i.vendor||'Restricted'}}</strong><span class="cell-secondary">{{i.orderNumber||'Restricted'}} · {{date(i.orderDate)}}</span></td><td>{{i.invoiceNumber||'Restricted'}}<span class="cell-secondary">{{date(i.invoiceDate)}}</span></td><td class="scope-cell">{{i.description||'Restricted'}}<span class="cell-secondary">{{i.category||'Restricted'}}</span></td><td><span class="status-badge" :class="iStatus(i)==='Closed'?'green':'amber'">{{iStatus(i)}}</span></td><td>{{showMoney(i.amount)}}</td><td>{{showMoney(balance(i))}}</td><td><v-btn v-if="allowed('amend')" variant="text" size="small" @click="open('invoice-status',i)">Amend status</v-btn></td></tr><tr v-if="!invoices.length"><td colspan="7" class="empty-state">Add a vendor invoice before recording a payment.</td></tr></tbody></table></div></section>
<section class="panel"><div class="panel-top"><div><h2>{{page==='expenses'?'Expense register':'Vendor payment work orders'}}</h2><p>Superuser direct approval, or Admin/Finance plus Superuser for regular submissions.</p></div><v-btn v-if="allowed('create')&&editable()" color="primary" prepend-icon="mdi-plus" @click="open('record')">{{page==='expenses'?'Add expense':'Record payment'}}</v-btn></div><div class="table-toolbar"><v-text-field v-model="query" prepend-inner-icon="mdi-magnify" label="Search records" hide-details density="compact"/></div><div class="table-scroll"><table class="orders-table"><thead><tr v-if="page==='expenses'"><th>DESCRIPTION / CATEGORY</th><th>PAYEE / DATE</th><th>VALUE</th><th>COST TREATMENT</th><th>APPROVAL</th><th>REMARKS</th><th></th></tr><tr v-else><th>DESCRIPTION</th><th>CATEGORY</th><th>WORK ORDER NO.</th><th>WORK ORDER DATE</th><th>INVOICE NO.</th><th>INVOICE DATE</th><th>INVOICE STATUS</th><th>PAID AMOUNT</th><th>TDS</th><th>PAID DATE</th><th>BALANCE AMOUNT</th><th>REMARKS</th><th>APPROVAL</th><th></th></tr></thead><tbody><tr v-for="d in records" :key="d.id"><template v-if="page==='expenses'"><td class="scope-cell">{{d.description||'Restricted'}}<span class="cell-secondary">{{d.category||'Restricted'}}</span></td><td>{{d.payee||'Restricted'}}<span class="cell-secondary">{{date(d.expenseDate)}}</span></td><td>{{showMoney(d.amount)}}</td><td>{{mode('reference')==='hidden'?'Restricted':d.referenceId?'Already in order · no extra cost':'Additional project cost'}}</td><td><span class="status-badge" :class="financeStatus(state,d)==='Approved'?'green':'amber'">{{financeStatus(state,d)}}</span></td><td class="scope-cell">{{d.remarks||'—'}}</td></template><template v-else><td class="scope-cell">{{inv(d.invoiceId)?.description||'Restricted'}}</td><td>{{inv(d.invoiceId)?.category||'Restricted'}}</td><td>{{inv(d.invoiceId)?.orderNumber||'Restricted'}}</td><td>{{date(inv(d.invoiceId)?.orderDate)}}</td><td>{{inv(d.invoiceId)?.invoiceNumber||'Restricted'}}</td><td>{{date(inv(d.invoiceId)?.invoiceDate)}}</td><td>{{inv(d.invoiceId)?iStatus(inv(d.invoiceId)):'Restricted'}}</td><td>{{showMoney(d.paid)}}</td><td>{{showMoney(d.tds)}}</td><td>{{date(d.paidDate)}}</td><td>{{showMoney(balance(inv(d.invoiceId)))}}</td><td class="scope-cell">{{d.remarks||'—'}}</td><td><span class="status-badge" :class="financeStatus(state,d)==='Approved'?'green':'amber'">{{financeStatus(state,d)}}</span></td></template><td><v-btn variant="text" size="small" @click="selected=d.id">View</v-btn></td></tr><tr v-if="!records.length"><td :colspan="page==='expenses'?7:14" class="empty-state">No records available in this project.</td></tr></tbody></table></div></section>
<v-dialog :model-value="!!active" @update:model-value="v=>{if(!v)selected=''}" max-width="780"><v-card v-if="active"><v-card-title class="dialog-title">{{active.kind==='expense'?'Expense details':'Vendor payment details'}}<v-btn icon="mdi-close" variant="text" @click="selected=''" aria-label="Close details"/></v-card-title><v-card-text><div class="approval-head"><span class="status-badge amber">{{financeStatus(state,active)}}</span><strong>{{showMoney(active.amount)}}</strong></div><p class="scope-detail mt-5">{{active.description||inv(active.invoiceId)?.description||'Description restricted'}}</p><p class="small muted">{{approvalRequirement(active)}}</p><div v-if="active.kind==='payment'" class="po-reference mt-5"><div><small>Invoice</small><strong>{{inv(active.invoiceId)?.invoiceNumber||'Restricted'}}</strong></div><div><small>Net paid / TDS</small><strong>{{showMoney(active.paid)}} / {{showMoney(active.tds)}}</strong></div><div><small>Paid date</small><strong>{{date(active.paidDate)}}</strong></div><div><small>Invoice balance</small><strong>{{showMoney(balance(inv(active.invoiceId)))}}</strong></div></div><p class="small mt-4">{{active.remarks||'No remarks'}}</p><div class="custom-data"><div v-for="(value,key) in active.data" :key="key"><small>{{key}}</small><strong>{{value}}</strong></div></div><v-alert v-if="failure" type="error" class="mt-4">{{failure}}</v-alert><div class="approval-actions"><v-btn v-if="financeStatus(state,active)==='Draft'&&allowed('edit')&&editable()&&(user.superuser||active.createdBy===user.id)" variant="outlined" @click="open('record',active)">Edit draft</v-btn><v-btn v-for="a in ['submit','review','approve','reject'].filter(a=>canFinanceAct(state,user,tenantId,active,a))" :key="a" :color="a==='reject'?'error':'primary'" :loading="busy" @click="action(active,a)">{{a==='approve'?approveLabel(active):a==='submit'?'Submit':a==='review'?'Complete review':'Reject'}}</v-btn></div><div v-for="e in state.financeEvents.filter(e=>e.documentId===active.id)" :key="e.id" class="event-line"><v-icon size="16">mdi-history</v-icon>{{e.action}} {{e.stage?approvalStageLabel(e.stage):''}} · {{who(e.actorId)}} · {{new Date(e.at).toLocaleString('en-IN')}}</div></v-card-text></v-card></v-dialog>
<v-dialog :model-value="!!dialog" @update:model-value="v=>{if(!v)dialog=''}" max-width="780"><v-card><v-card-title class="dialog-title">{{dialog==='invoice'?'Register vendor invoice':dialog==='invoice-status'?'Amend invoice status':page==='expenses'?'Construction expense':'Vendor payment work order'}}<v-btn icon="mdi-close" variant="text" aria-label="Close form" @click="dialog=''"/></v-card-title><v-card-text><v-alert v-if="error||failure" type="error" class="mb-4">{{error||failure}}</v-alert><v-form ref="formRef" @submit.prevent="save"><template v-if="dialog==='invoice-status'"><v-select v-model="form.status" :items="['Open','Closed']" label="Invoice status *"/><v-textarea v-model="form.reason" label="Reason for amendment *" :rules="[required]" rows="2"/><p class="small muted">Status changes retain a dated history. An invoice with an outstanding balance cannot be closed.</p><div v-for="e in state.invoiceEvents.filter(e=>e.invoiceId===form.id)" :key="e.id" class="event-line">{{e.status}} · {{e.reason}} · {{who(e.actorId)}} · {{new Date(e.at).toLocaleString('en-IN')}}</div></template><template v-else-if="dialog==='invoice'"><v-select v-model="form.orderId" :items="orders.map(o=>({title:o.number+' · '+o.vendor,value:o.id}))" label="Work order *" :rules="[required]"/><div v-if="form.orderId" class="dialog-context">{{orders.find(o=>o.id===form.orderId)?.vendor}} · Work order date {{date(orders.find(o=>o.id===form.orderId)?.orderDate||orders.find(o=>o.id===form.orderId)?.createdAt?.slice(0,10))}}</div><v-text-field v-model="form.description" label="Description *" :rules="[required]"/><v-combobox v-model="form.category" :items="expenseCategories" label="Category · choose or type *" :rules="[required]"/><div class="form-two-columns"><v-text-field v-model="form.invoiceNumber" label="Invoice number *" :rules="[required]"/><v-text-field v-model="form.invoiceDate" type="date" label="Invoice date *" :rules="[dateRule]"/></div><v-text-field v-model="form.price" label="Invoice amount incl. tax (₹) *" inputmode="decimal" :rules="[required,amountRule]"/><v-textarea v-model="form.remarks" label="Remarks" rows="2"/></template><template v-else><template v-if="page==='expenses'"><v-text-field v-model="form.description" label="Description *" :rules="[required]"/><v-combobox v-model="form.category" :items="expenseCategories" label="Category · choose or type *" :rules="[required]"/><v-text-field v-model="form.payee" label="Consultant / payroll / supplier / payee *" :rules="[required]"/><div class="form-two-columns"><v-text-field v-model="form.expenseDate" type="date" label="Expense date *" :rules="[dateRule]"/><v-text-field v-model="form.price" label="Amount incl. tax (₹) *" inputmode="decimal" :rules="[required,amountRule]"/></div><v-select v-model="form.referenceType" :items="[{title:'Additional cost · add to project total',value:''},{title:'Already covered by a work order',value:'work_order'},{title:'Already covered by a purchase order',value:'purchase_order'}]" label="Cost treatment" @update:model-value="form.referenceId=''"/><v-select v-if="form.referenceType" v-model="form.referenceId" :items="refs.map(r=>({title:r.number,value:r.id}))" label="Related order *" :rules="[required]"/></template><template v-else><v-select v-model="form.invoiceId" :items="invoices.filter(i=>iStatus(i)==='Open'&&balance(i)>0).map(i=>({title:i.invoiceNumber+' · '+i.vendor+' · '+money(balance(i))+' balance',value:i.id}))" label="Open invoice *" :rules="[required]"/><div v-if="inv(form.invoiceId)" class="dialog-context">{{inv(form.invoiceId).orderNumber}} · {{inv(form.invoiceId).description}}<br>Invoice {{date(inv(form.invoiceId).invoiceDate)}} · Balance {{showMoney(balance(inv(form.invoiceId)))}}</div><div class="form-two-columns"><v-text-field v-model="form.price" label="Net paid to vendor (₹) *" inputmode="decimal" :rules="[required,amountRule]"/><v-text-field v-model="form.tax" label="TDS amount (₹) *" inputmode="decimal" :rules="[required,amountRule]"/></div><v-text-field v-model="form.paidDate" label="Paid date *" type="date" :rules="[dateRule]"/><p class="small muted mb-5">Enter the TDS amount separately. No tax rate is assumed. Settlement is net paid plus TDS.</p></template><v-textarea v-model="form.remarks" label="Remarks" rows="2"/><template v-for="f in extra" :key="f.key"><v-text-field v-if="mode(f.key)==='edit'" v-model="form.data[f.key]" :label="f.label+(f.required?' *':'')" :type="f.type==='date'?'date':f.type==='number'?'number':'text'" :rules="f.required?[required]:[]"/></template></template></v-form></v-card-text><v-card-actions class="dialog-actions"><v-btn @click="dialog=''">Cancel</v-btn><v-spacer/><v-btn color="primary" :loading="busy" @click="save">{{dialog==='invoice-status'?'Save amendment':dialog==='invoice'?'Register invoice':'Save draft'}}</v-btn></v-card-actions></v-card></v-dialog>
</template>
